{
    using namespace HorizonChatTest;FHorizonChatSynced V;const FString S=Sync(Channel());TestTrue(TEXT("Empty complete snapshot and max safe revision"),Read(S,V)&&V.Channel.Revision==9007199254740991LL&&!V.Moderation.bHasMuteUntil&&!V.Moderation.bHasBanUntil);
    for(const auto& Bad:{S.Replace(TEXT("9007199254740991"),TEXT("9007199254740991.1")),S.Replace(TEXT("9007199254740991"),TEXT("9007199254740992")),S.Replace(TEXT(".000Z"),TEXT("Z")),S.Replace(TEXT("\"groupId\":null,"),TEXT("")),S.Replace(TEXT("\"kind\":\"project\""),TEXT("\"kind\":\"direct\"")),S.Replace(TEXT("\"revision\":9007199254740991"),TEXT("\"revision\":1,\"rev\\u0069sion\":2")),S.Replace(TEXT("\"messages\":[]"),TEXT("\"messages\":[],\"unknown\":true"))})TestFalse(TEXT("Malformed source rejected without coercion"),Read(Bad,V));
    TestTrue(TEXT("Non-BMP, LF, TAB literal text"),HorizonChatWire::Text(TEXT("snow 雪 😀\n\t")));FString Emoji;for(int I=0;I<500;++I)Emoji+=TEXT("😀");TestTrue(TEXT("500 Unicode scalars, 2000 UTF8 bytes"),HorizonChatWire::Text(Emoji));TestFalse(TEXT("501 Unicode scalars"),HorizonChatWire::Text(Emoji+TEXT("a")));FString Nul;auto& Chars=Nul.GetCharArray();Chars.SetNumUninitialized(4);Chars[0]='a';Chars[1]=0;Chars[2]='b';Chars[3]=0;TestFalse(TEXT("NUL not accepted"),HorizonChatWire::Text(Nul));TestFalse(TEXT("CR not accepted"),HorizonChatWire::Text(TEXT("a\r")));TestFalse(TEXT("All Java whitespace blank"),HorizonChatWire::Text(TEXT("\u00a0\u2007\u202f\u2000\u3000\t")));FString Escaped;for(int I=0;I<500;++I)Escaped+=TEXT("\\ud83d\\ude00");FString Ids,Rows;for(int I=0;I<20;++I){const FString RowId=FGuid(0,0,0,uint32(I+1)).ToString(EGuidFormats::DigitsWithHyphens).ToLower();if(I){Ids+=TEXT(",");Rows+=TEXT(",");}Ids+=TEXT("\"")+RowId+TEXT("\"");Rows+=TEXT("{\"id\":\"")+RowId+TEXT("\",\"channelId\":\"")+HorizonChatTest::Id+TEXT("\",\"authorId\":\"")+User+TEXT("\",\"text\":\"")+Escaped+TEXT("\",\"createdAt\":\"2026-10-16T00:00:00.000Z\",\"expiresAt\":\"2026-10-23T00:00:00.000Z\"}");}const FString Large=S.Replace(TEXT("\"visibleMessageIds\":[]"),*(TEXT("\"visibleMessageIds\":[")+Ids+TEXT("]"))).Replace(TEXT("\"messages\":[]"),*(TEXT("\"messages\":[")+Rows+TEXT("]")));TestTrue(TEXT("20 fully escaped max-Unicode messages fit bounded wire"),Large.Len()>120000&&Read(Large,V)&&V.Messages.Num()==20&&HorizonChatWire::Utf8(V.Messages[19].Text).size()==2000);return true;
}
